p138:
  catalogo-subcuenta:
    por-defecto: 182
    especiales:
      "5000": { catalogo: 183, offset: 500000000000 }   # S080-CDPE-CVE-REGIST = cuenta - offset

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class CatalogoCuentas {
    private final CatalogoS080Client s080;       // L700_CONSUL_DESC IN S080BD01CON
    private final P138Properties props;

    @Cacheable("nombreSubcuenta")
    String nombre(String cuenta12) {
        var regla = props.catalogoSubcuenta().para(cuenta12.substring(0, 4));
        long clave = Long.parseLong(cuenta12) - regla.offset();
        // el COBOL asigna la fecha de consulta y la sobrescribe con 0 en la línea siguiente
        return s080.consultaDescripcion(151, 138, regla.catalogo(), 20, clave, /* fecha */ 0)
                   .map(Descripcion::textoCorto)
                   .orElse("");                   // resultado distinto de 0 o 1: nombre en blanco
    }
}

